from collections import deque

def solve(g):
    h,w=len(g),len(g[0])
    rowbar=[sum(1 for x in row if x==8)>=5 for row in g]
    colbar=[sum(1 for r in range(h) if g[r][c]==8)>=5 for c in range(w)]
