        if rowbar[r] and c>0 and c<w-1 and g[r][c-1]==8 and g[r][c+1]==8: return True
        return False
    # bands: connected non-gap 0/2 cells
    band=[[-1]*w for _ in range(h)]; nb=0
    for r in range(h):
        for c in range(w):
            if g[r][c]!=8 and not isgap(r,c) and band[r][c]==-1:
                q=deque([(r,c)]); band[r][c]=nb
                while q:
                    a,b=q.popleft()
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and g[x][y]!=8 and not isgap(x,y) and band[x][y]==-1:
