    if r0==0: d=(1,0)
    elif r0==h-1: d=(-1,0)
    elif c0==0: d=(0,1)
    else: d=(0,-1)
    def band_beyond(r,c,dr,dc,fb):
        x,y=r+dr,c+dc
        if 0<=x<h and 0<=y<w and not isgap(x,y) and g[x][y]!=8: return band[x][y]
        return fb
    out=[row[:] for row in g]
    seen=set(); stack=[(r0,c0,d[0],d[1],frozenset([band[r0][c0]]))]
    while stack:
        r,c,dr,dc,bs=stack.pop()
        if (r,c,dr,dc,bs) in seen: continue
        seen.add((r,c,dr,dc,bs))
        if out[r][c]==0: out[r][c]=2
        while True:
            turns=[]
            for p in ((dc,dr),(-dc,-dr)):
                x,y=r+p[0],c+p[1]
                if 0<=x<h and 0<=y<w and isgap(x,y):
                    tb=band_beyond(x,y,p[0],p[1],None)
                    if tb is None or tb not in bs: turns.append((p,tb))
            if turns:
                for p,tb in turns[1:]:
                    stack.append((r,c,p[0],p[1],bs|({tb} if tb is not None else set())))
                (p,tb)=turns[0]; dr,dc=p
                if tb is not None: bs=bs|{tb}
                continue
            nr,nc=r+dr,c+dc
            if not (0<=nr<h and 0<=nc<w): break
            if g[nr][nc]==8:
                stack.append((r,c,dc,dr,bs)); stack.append((r,c,-dc,-dr,bs))
                break
            r,c=nr,nc
            if out[r][c]==0: out[r][c]=2
            if isgap(r,c):
                tb=band_beyond(r,c,dr,dc,band[r-dr][c-dc] if False else None)
                bs=bs|({tb} if tb is not None else set())
    return out

